## set_temp_variable

* Supported Scopes: any
* Supported Targets: none

Sets a temp variable to a value, another variable, or a [math expression](script_math_expression.md).
`tooltip` can be used to override tooltip title with LEFT and RIGHT tokens.

### Examples
```
set_temp_variable = { num_dogs = 42 }
set_temp_variable = {
	var = num_dogs
	value = 42
	tooltip = loc_str_id_with_LEFT_and_RIGHT
}
set_temp_variable = {
	num_dogs = { value = num_cats  multiply = 2  add = 1 }
}
```

#EFFECTS FROM PURGES
SOV_paranoia_daunt_generals_effect = {
	set_temp_variable = { temp_targets_index = 0 }

	while_loop_effect = {
		limit = {
			check_variable = { temp_targets_index = 5 compare = less_than }
			any_army_leader = {
				NOT = { has_character_flag = SOV_targeted_for_purge_flag }
				NOT = { has_trait = trait_SOV_cowed_by_stalin_army }
			}
		}
		random_army_leader = {
			limit = {
				NOT = { has_character_flag = SOV_targeted_for_purge_flag }
				NOT = { has_trait = trait_SOV_cowed_by_stalin_army }
			}
			add_unit_leader_trait = trait_SOV_cowed_by_stalin_army
		}
		add_to_temp_variable = { temp_targets_index = 1 }
		#log = "LOOP ROUND [?temp_targets_index]"
	}

	custom_effect_tooltip = SOV_daunt_generals_tt
